import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"事件 API","description":"","frontmatter":{},"headers":[],"relativePath":"modules/forge/events.md","filePath":"modules/forge/events.md","lastUpdated":0}`),a={name:`modules/forge/events.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="事件-api" tabindex="-1">事件 API <a class="header-anchor" href="#事件-api" aria-label="Permalink to “事件 API”">​</a></h1><p>Forge 事件位于 <code>emaki.jiuwu.craft.forge.api.event</code>，均为玩家 owner thread 上的同步 Bukkit 事件。当前 GUI 锻造与公开 <code>ForgeOperations.forgeAsync</code> 共用事件契约。</p><table tabindex="0"><thead><tr><th>事件</th><th>触发时机</th><th>线程</th><th>Cancellable</th><th>可修改字段</th><th>取消/结果效果</th><th>runtime 路径</th></tr></thead><tbody><tr><td><code>ForgeStartEvent</code></td><td>验证和 prepared forge 完成后、异步执行与材料提交前</td><td>玩家 owner thread</td><td>是</td><td><code>successRate</code>，有限值 clamp 到 0–100，非有限值变 0</td><td>取消时不排程执行、不消耗材料；API 返回 <code>CANCELLED</code></td><td>GUI 确认与 <code>forgeAsync</code></td></tr><tr><td><code>ForgeCompletedEvent</code></td><td>正常 forge result 已解析后，成功或可解析失败均可触发</td><td>玩家 owner thread</td><td>否</td><td>无</td><td>post 通知，不可回滚</td><td>GUI 完成与 <code>forgeAsync</code> 完成</td></tr></tbody></table><p><code>ForgeStartEvent</code> 的 player、recipeId、firstCraft 为只读。<code>ForgeCompletedEvent</code> 的 success、resultItem、quality、multiplier 为只读；失败时 resultItem/quality 可为空。</p><p>当 owner/generation 验证在 start 前失败时不会发开始事件。完成阶段若玩家 owner 调度已退役，结果仍会映射/结算，但 completed event 可被跳过。取消 start 不会产生 completed event。Catalog 校验、打开 GUI/配方书和刷新物品本身不属于一次 forge attempt。</p>`,5)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};